function setINLang(c){const t={...IN_LANG.en,...(IN_LANG[c]||{}) ,...(COMMUNITY_LANG[c]||{}),...(RANKING_LANG[c]||{}),...(PROFILE_LANG[c]||{}),...(SETTINGS_LANG[c]||{}),...(AUTHOR_STUDIO_LANG[c]||{}),...(COMMUNITY_EXPANSION_LANG[c]||{}),...(LIBRARY_LANG[c]||{})};try{localStorage.setItem("imperial_language",c)}catch(e){}document.documentElement.lang=c;document.documentElement.dir=(c==="ur"||c==="ar")?"rtl":"ltr";const setLabel=(e,k)=>{const key=e.dataset.inLangKey||(e.dataset.inLangKey=k||e.textContent.trim());if(!t[key]){if(e.matches(".mobileNav a")){const n=[...e.childNodes].find(n=>n.nodeType===3&&n.textContent.trim());if(n)n.textContent=key}else e.textContent=key;return}if(e.matches(".mobileNav a")){const n=[...e.childNodes].find(n=>n.nodeType===3&&n.textContent.trim());if(n)n.textContent=t[key]}else e.textContent=t[key]};document.querySelectorAll(".navlinks a,.menuDrawer a span,.footerLinks a,.mobileNav a").forEach(e=>setLabel(e));document.querySelectorAll('[data-in-lang]').forEach(e=>{const key=e.dataset.inLangKey||(e.dataset.inLangKey=e.textContent.trim());e.textContent=t[key]||key});document.querySelectorAll('[data-in-lang-placeholder]').forEach(e=>{const key=e.dataset.inLangPlaceholder;e.placeholder=t[key]||key});document.querySelectorAll("[data-tooltip]").forEach(e=>{const key=e.dataset.inLangTooltip||(e.dataset.inLangTooltip=e.getAttribute("data-tooltip"));e.setAttribute("data-tooltip",t[key]||key)});document.querySelectorAll("button[aria-label],input[aria-label],nav[aria-label],aside[aria-label]").forEach(e=>{if(e.id==="imperialMenuToggle")return;const key=e.dataset.inLangAria||(e.dataset.inLangAria=e.getAttribute("aria-label"));e.setAttribute("aria-label",t[key]||key)});document.querySelectorAll("[title]").forEach(e=>{if(e.matches("[data-theme-toggle]"))return;const key=e.dataset.inLangTitle||(e.dataset.inLangTitle=e.getAttribute("title"));e.setAttribute("title",t[key]||key)});const menuButton=document.querySelector("#imperialMenuToggle");if(menuButton){const key=menuButton.getAttribute("aria-expanded")==="true"?"Close navigation menu":"Open navigation menu";menuButton.setAttribute("aria-label",t[key]||key)}const themeButton=document.querySelector("[data-theme-toggle]");if(themeButton){const key=document.documentElement.dataset.theme==="dark"?"Switch to light mode":"Switch to dark mode";themeButton.setAttribute("aria-label",t[key]||key);themeButton.setAttribute("title",t[key]||key)}const drawerLabel=document.querySelector(".menuDrawerLabel");if(drawerLabel){const key=drawerLabel.dataset.inLangKey||(drawerLabel.dataset.inLangKey="Explore the realm");drawerLabel.textContent=t[key]||key}const footerTagline=document.querySelector(".footerInner>div:first-child>div");if(footerTagline){const key=footerTagline.dataset.inLangKey||(footerTagline.dataset.inLangKey="Original, licensed and authorized stories.");footerTagline.textContent=t[key]||key}const s=document.querySelector("#imperialLanguageSelect");if(s&&s.value!==c)s.value=c}function initINLang(){let c="en";try{c=localStorage.getItem("imperial_language")||"en"}catch(e){}const s=document.querySelector("#imperialLanguageSelect");if(s){s.value=c;s.addEventListener("change",()=>setINLang(s.value))}setINLang(c)}
