 root.innerHTML=pageStart('Account','Your personal Imperial command room.')+`<div class="accountGrid"><aside class="accountMenu" aria-label="Your reader profile navigation"><a class="active" href="/account" data-in-lang>Profile</a><a href="/library" data-in-lang>Library</a><a href="/history" data-in-lang>History</a><a href="/following" data-in-lang>Following</a><a href="/tickets" data-in-lang>Imperial Crown Vault</a><a href="/requests" data-in-lang>Requests</a><a href="/omniportal" data-in-lang>OmniPortal</a><button id="logout" class="ghost" style="width:100%;margin-top:8px" data-in-lang>Sign out</button></aside><main><div class="panel"><div class="profileTop"><img class="avatar" src="/story-cover-placeholder.svg" alt=""><div><h2 style="margin:0">${esc(p.user.username)}</h2><div class="muted">${esc(p.user.email)}</div></div></div><div class="metricGrid"><div class="metric"><b>${p.user.tickets}</b><div class="muted" data-in-lang>Imperial Crowns</div></div><div class="metric"><b>${p.stats.history}</b><div class="muted" data-in-lang>Library</div></div><div class="metric"><b>${p.stats.following}</b><div class="muted" data-in-lang>Following</div></div><div class="metric"><b>${p.stats.unlocks}</b><div class="muted" data-in-lang>Unlocks</div></div></div></div><div class="panel" style="margin-top:15px"><h2 data-in-lang>Recommendations</h2><div id="recs" class="grid"></div></div></main></div></div>`;
 const title=root.querySelector('.title h1');if(title)title.dataset.inLang='';
