function applyLibraryTranslations(root,language){root.querySelectorAll('*').forEach(el=>{if(el.children.length===0){const key=el.textContent.trim();if(LIBRARY_LANG.en[key])el.dataset.inLang=''}});setINLang(language)}
async function library(mode='library'){const root=$('#app');let activeLanguage='en';try{activeLanguage=localStorage.getItem('imperial_language')||'en'}catch{}const localizeLibrary=()=>applyLibraryTranslations(root,activeLanguage);const libraryObserver=new MutationObserver(()=>localizeLibrary());libraryObserver.observe(root,{childList:true,subtree:true});try{const me=await api('/api/me');if(!me.user){root.innerHTML=pageStart('My Library','Sign in to save stories and sync your reading across devices.')+`<div class="panel"><p>Your library is available after signing in.</p><a class="primary" href="/login">Sign In</a><a class="secondary" href="/register">Create Account</a></div></div></div>`;localizeLibrary();return}const [items,historyRows,bookmarks,following]=await Promise.all([api('/api/library'),api('/api/history'),api('/api/bookmarks'),api('/api/follows')]);const active=mode==='following'?'following':'library';root.innerHTML=pageStart('My Library','Your saved stories, reading progress and bookmarks, synced to your account.')+`<div class="tabs"><a class="${active==='library'?'active':''}" href="/library">My Library</a><a href="/history">History</a><a class="${active==='following'?'active':''}" href="/following">Following</a></div><section class="section"><div class="sectionHead"><div><h2>Continue Reading</h2><p>Jump back into your most recently read stories.</p></div></div><div class="grid" id="continueList"></div></section><section class="section"><div class="sectionHead"><div><h2>Saved Stories</h2><p id="savedCount">${items.length} novel${items.length===1?'':'s'} in your library.</p></div></div><div class="grid" id="savedList"></div></section><section class="section"><div class="sectionHead"><div><h2>Bookmarked Chapters</h2><p>Your saved chapter positions.</p></div></div><div id="bookmarkList" class="panel"></div></section></div></div>`;const cont=historyRows.slice(0,12);$('#continueList').innerHTML=cont.length?cont.map(x=>`<article class="panel"><div class="muted">${esc(x.author||'Unknown author')}</div><h3>${esc(x.title)}</h3><p>Chapter ${Number(x.chapter_number)} · ${Math.min(100,Math.max(0,Number(x.progress_percent)||0))}%</p><a class="primary" href="/read/${x.novel_id}/${Number(x.chapter_number)}">Continue Reading →</a></article>`).join(''):`<div class="empty" style="grid-column:1/-1">No reading history yet. Open a chapter to begin.</div>`;$('#savedList').innerHTML=items.length?items.map(x=>`<article class="card"><a href="/novel/${x.novel_id}"><div class="cover"><img src="${img(x.cover_url)}" alt="${esc(x.title)} cover" loading="lazy" decoding="async" fetchpriority="low"></div><div class="cardBody"><div class="cardTitle">${esc(x.title)}</div><div class="muted">${esc(x.author||'Unknown author')}</div><div class="meta"><span>${Number.isFinite(Number(x.rating))&&Number(x.rating)>=1&&Number(x.rating)<=5?'★ '+Math.round(Number(x.rating))+'/5':''}</span><span>${x.latest_chapter?`${Number(x.latest_chapter)} ch.`:'No chapters'}</span></div></div></a><div style="padding:0 13px 13px"><button class="ghost removeLibrary" data-id="${x.novel_id}" type="button">Remove from Library</button></div></article>`).join(''):`<div class="empty" style="grid-column:1/-1">Your library is empty. Open a novel and tap <b>Add to Library</b>.</div>`;$('#bookmarkList').innerHTML=bookmarks.length?bookmarks.map(x=>`<div class="statline"><span><b>${esc(x.title)}</b> · Chapter ${Number(x.chapter_number)}</span><span><a class="ghost" href="/read/${x.novel_id}/${Number(x.chapter_number)}">Open</a> <button class="ghost removeBookmark" data-novel-id="${x.novel_id}" data-chapter-number="${Number(x.chapter_number)}" type="button" aria-label="Remove bookmark">Remove bookmark</button></span></div>`).join(''):`<div class="empty">No bookmarked chapters yet.</div>`;localizeLibrary();$('.removeLibrary').forEach(b=>b.onclick=async()=>{try{await api('/api/library',{method:'POST',body:JSON.stringify({novel_id:Number(b.dataset.id)})});b.closest('.card')?.remove();const remaining=$('.removeLibrary').length;$('#savedCount').textContent=remaining+' novel'+(remaining===1?'':'s')+' in your library.';if(!remaining)$('#savedList').innerHTML='<div class="empty" style="grid-column:1/-1">Your library is empty. Open a novel and tap <b>Add to Library</b>.</div>';localizeLibrary()}catch(e){alert(e.message)}});$('.removeBookmark').forEach(b=>b.onclick=async()=>{try{await api('/api/bookmark',{method:'DELETE',body:JSON.stringify({novel_id:Number(b.dataset.novelId),chapter_number:Number(b.dataset.chapterNumber)})});b.closest('.statline')?.remove();if(!$('.removeBookmark').length)$('#bookmarkList').innerHTML='<div class="empty">No bookmarked chapters yet.</div>';localizeLibrary()}catch(e){alert(e.message)}})}catch(e){root.innerHTML=pageStart('My Library')+`<div class="notice">${esc(e.message)} <a href="/login" style="color:var(--gold2)">Sign in</a></div></div></div>`}}
async function history(){const root=$('#app');let language='en';try{language=localStorage.getItem('imperial_language')||'en'}catch{}try{const d=await api('/api/history');root.innerHTML=pageStart('Reading History','Your recently read novels and the latest chapters you reached.')+`<div class="grid" id="historyList"></div></div></div>`;applyLibraryTranslations(root,language);$('#historyList').innerHTML=d.length?d.map(n=>card({...n,chapter_count:`Ch ${n.chapter_number}`})).join(''):`<div class="empty" style="grid-column:1/-1">No reading history yet. Open a chapter to begin your journey.</div>`;applyLibraryTranslations(root,language)}catch(e){root.innerHTML=pageStart('Reading History','Your recently read novels and the latest chapters you reached.')+`<div class="notice">${esc(e.message)} <a href="/login" style="color:var(--gold2)">Sign in</a></div></div></div>`}}
async function following(){await library('following')}
async function tickets(){const root=$('#app');try{const [p,l]=await Promise.all([api('/api/profile'),api('/api/tickets/ledger')]);root.innerHTML=pageStart('Imperial Crown Vault','Your Imperial Crown balance and complete transaction ledger.')+`<div class="panel"><div class="metricGrid"><div class="metric"><b>${p.user.tickets}</b><div class="muted">Current balance</div></div><div class="metric"><b>${p.stats.ticketFlow}</b><div class="muted">Net Crown flow</div></div></div><div class="section"><h2 style="font:600 25px Georgia,serif">Ledger</h2><div class="chapterList">${l.length?l.map(x=>`<div class="chapter"><span class="chapterNo">${x.delta>0?'+':''}${x.delta}</span><span><b>${esc(x.reason)}</b><br><span class="muted">${esc(x.created_at)} · ${esc(x.reference||'')}</span></span><span>${x.delta>0?'Credit':'Debit'}</span></div>`).join(''):`<div class="empty">No Imperial Crown transactions yet.</div>`}</div></div><div class="notice" style="margin-top:18px">Batch unlock sizes supported: 10, 25, 50 and 100 chapters.</div></div></div>`}catch(e){root.innerHTML=pageStart('Imperial Crown Vault')+`<div class="notice">${esc(e.message)} <a href="/login" style="color:var(--gold2)">Sign in</a></div></div></div>`}}
async function requests(){const root=$('#app');let r;try{r=await api('/api/requests')}catch(e){root.innerHTML=pageStart('Request a New Novel','Three free requests each week, then Imperial Crown pricing applies.')+`<div class="notice">${esc(e.message)} <a href="/login" style="color:var(--gold2)">Sign in</a></div></div></div>`;return}root.innerHTML=pageStart('Request a New Novel','Three free requests each week, then Imperial Crown pricing applies.')+`<div class="panel" style="max-width:720px"><div class="stats"><div class="stat"><b>${r.used}/${r.limit}</b>Free requests used</div></div><form id="req"><div class="field"><label>Novel URL</label><input name="url" placeholder="https://example.com/novel/..." required></div><button class="primary">Submit Request</button></form><div id="reqMsg" style="margin-top:12px"></div></div></div></div>`;$('#req').onsubmit=async e=>{e.preventDefault();try{const d=await api('/api/requests',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});$('#reqMsg').innerHTML=`<div class="notice">${esc(d.message)} Cost: ${d.cost} Imperial Crowns.</div>`;e.target.reset()}catch(x){$('#reqMsg').innerHTML=`<div class="notice">${esc(x.message)}</div>`}}}
async function omni(){
 const root=$('#app');
 root.innerHTML=pageStart('OmniPortal','Rights-first discovery across Imperial Novel and authorized provider connectors.')+`<div class="panel"><form id="omni" class="toolbar"><div class="search" style="display:flex"><span>✦</span><input name="q" placeholder="Search titles, authors and worlds..."></div><button class="primary">Search</button></form><div class="notice"><b>Legal mode:</b> only authorized connectors are queried. Imports are metadata-only by default. Imperial Novel does not bypass paywalls, DRM, logins or access controls, and does not copy source chapters.</div><div id="omniRes" class="grid" style="margin-top:18px"></div></div></div></div>`;
 $('#omni').onsubmit=async e=>{
  e.preventDefault();
  const q=String(new FormData(e.target).get('q')||'');
  if(q.length<2)return;
  try{
   const d=await api('/api/omni/search?q='+encodeURIComponent(q));
   if(!d.results.length){$('#omniRes').innerHTML='<div class="empty" style="grid-column:1/-1">No authorized results found.</div>';return;}
   $('#omniRes').innerHTML=d.results.map(x=>{
    const ext=String(x.url||'').startsWith('http');
    return `<div class="card"><div class="cardBody"><span class="pill purple">${esc(x.provider)}</span><div class="cardTitle" style="margin-top:10px">${esc(x.title)}</div><div class="muted">${esc(x.author)}</div><p class="muted">${esc(x.description||'')}</p><div class="actions" style="margin-top:12px">${ext?`<a class="ghost" href="${esc(x.url)}" target="_blank" rel="noopener">Open Source</a><button class="secondary omniImport" data-url="${esc(x.url)}">Request Metadata Import</button>`:`<a class="primary" href="${esc(x.url)}">Read on Imperial Novel</a>`}</div></div></div>`;
   }).join('');
   document.querySelectorAll('.omniImport').forEach(btn=>{
    btn.onclick=async()=>{
     try{
      const d=await api('/api/omni/import',{method:'POST',body:JSON.stringify({url:btn.dataset.url})});
      alert(`Metadata import request #${d.job_id} queued. No source chapters will be copied.`);
     }catch(err){alert(err.message)}
    };
   });
  }catch(err){alert(err.message)}
 };
}
