async function discoveryPage(kind){
 const root=$('#app');
 let activeLanguage='en';try{activeLanguage=localStorage.getItem('imperial_language')||'en'}catch{}
 const localizeDiscovery=()=>{root.querySelectorAll('*').forEach(el=>{if(el.children.length===0){const key=el.textContent.trim();if(COMMUNITY_EXPANSION_LANG.en[key]||COMMUNITY_LANG.en[key])el.dataset.inLang=''}});setINLang(activeLanguage)};
 const discoveryObserver=new MutationObserver(()=>localizeDiscovery());
 discoveryObserver.observe(root,{childList:true,subtree:true});
 if(kind==='community'){
  root.innerHTML=pageStart('Community','Discuss stories, discover readers, and help shape the Imperial catalog.')+`<section class="quickGrid"><a class="quickCard" href="/leaderboard"><span>♛</span><div><b data-in-lang>Leaderboard</b><small data-in-lang>Explore reader and story activity.</small></div></a><a class="quickCard" href="/tier-list"><span>▣</span><div><b data-in-lang>Tier List</b><small data-in-lang>Browse S, A, B and C story tiers.</small></div></a><a class="quickCard" href="/vote"><span>♜</span><div><b data-in-lang>Vote Novels</b><small data-in-lang>Support requests the community wants to see.</small></div></a><a class="quickCard" href="/random"><span>✦</span><div><b data-in-lang>Random Novel</b><small data-in-lang>Let the Imperial library choose.</small></div></a></section><section class="section"><div class="sectionHead"><div><h2 data-in-lang>Trending Stories</h2><p data-in-lang>Popular stories and fresh activity.</p></div><a class="ghost" href="/catalog?sort=trending" data-in-lang>View all</a></div><div id="communityGrid" class="grid" aria-live="polite"></div></section><section class="unlockBanner"><div><div class="eyebrow" data-in-lang>Community discovery</div><h2 data-in-lang>Find your next world</h2><p data-in-lang>Use personalized recommendations, rankings, requests and voting to explore the catalog.</p></div><a class="primary" href="/made-for-you" data-in-lang>Made For You →</a></section></div></div>`;
  const title=root.querySelector('.title h1');if(title)title.dataset.inLang='';
  const subtitle=root.querySelector('.title .sub');if(subtitle)subtitle.dataset.inLang='';
  localizeDiscovery();
  const d=await api('/api/novels?sort=trending&limit=12');
  $('#communityGrid').innerHTML=(d.results||[]).map(card).join('')||'<div class="empty" style="grid-column:1/-1" data-in-lang>No published novels yet.</div>';
  localizeDiscovery();return;
 }
 if(kind==='trending'){
  root.innerHTML=pageStart('Trending Now','Popular stories and fresh activity across the Imperial catalog.')+`<section class="section"><div class="sectionHead"><div><h2>Trending Stories</h2><p>Discover what readers are exploring now.</p></div><a class="ghost" href="/catalog?sort=trending">Catalog →</a></div><div id="trendingGrid" class="grid"></div></section></div></div>`;localizeDiscovery();const d=await api('/api/novels?sort=trending&limit=24');$('#trendingGrid').innerHTML=(d.results||[]).map(card).join('')||'<div class="empty" style="grid-column:1/-1">No published novels yet.</div>';localizeDiscovery();return;
 }
 if(kind==='leaderboard'){
  root.innerHTML=pageStart('Leaderboard','Story and author activity, with weekly, monthly and all-time views.')+`<div class="tabs"><a class="period active" data-period="weekly" data-in-lang>Weekly</a><a class="period" data-period="monthly" data-in-lang>Monthly</a><a class="period" data-period="all" data-in-lang>All Time</a></div><section class="section"><div class="sectionHead"><div><h2 data-in-lang>Top Novels</h2><p data-in-lang>Based on published catalog activity.</p></div></div><div id="lbNovels" class="grid" aria-live="polite"></div></section><section class="section"><div class="sectionHead"><div><h2 data-in-lang>Top Authors</h2><p data-in-lang>Authors with published stories.</p></div></div><div id="lbAuthors" class="grid" aria-live="polite"></div></section></div></div>`;
  const title=root.querySelector('.title h1');if(title)title.dataset.inLang='';const subtitle=root.querySelector('.title .sub');if(subtitle)subtitle.dataset.inLang='';
  localizeDiscovery();
  async function load(period){const d=await api('/api/leaderboard?period='+period);const t={...IN_LANG.en,...(IN_LANG[activeLanguage]||{}),...(COMMUNITY_LANG[activeLanguage]||{}),...(RANKING_LANG[activeLanguage]||{})};$('#lbNovels').innerHTML=(d.novels||[]).map((n,i)=>`<article class="panel"><div class="rankBadge">#${i+1}</div><div class="cardTitle">${esc(n.title)}</div><div class="muted">${esc(n.author||t.Unknown)}</div><div class="meta"><span>★ ${Number(n.rating||0).toFixed(1)}</span><span>◉ ${Number(n.views||0).toLocaleString()} <span data-in-lang>views</span></span><span>◷ ${Number(n.chapter_count||0)} <span data-in-lang>ch.</span></span></div><a class="ghost" href="/novel/${n.id}" data-in-lang>Open Novel →</a></article>`).join('')||'<div class="empty" data-in-lang>No ranked novels yet.</div>';$('#lbAuthors').innerHTML=(d.authors||[]).map((x,i)=>`<article class="panel"><div class="rankBadge">#${i+1}</div><h3>${esc(x.author)}</h3><div class="meta"><span>${Number(x.novels||0)} <span data-in-lang>novels</span></span><span>★ ${Number(x.rating||0).toFixed(1)}</span><span>◉ ${Number(x.views||0).toLocaleString()} <span data-in-lang>views</span></span></div><a class="ghost" href="/catalog?author=${encodeURIComponent(x.author)}" data-in-lang>View stories →</a></article>`).join('')||'<div class="empty" data-in-lang>No ranked novels yet.</div>';localizeDiscovery()}
  $('.period').forEach(b=>b.onclick=()=>{$('.period').forEach(x=>x.classList.remove('active'));b.classList.add('active');load(b.dataset.period)});load('weekly');return;
 }
 if(kind==='tier-list'){
  root.innerHTML=pageStart('Tier List','A simple discovery view based on published ratings and activity. It is not an official quality judgment.')+`<div id="tiers" class="tierGrid" aria-live="polite"></div></div></div>`;const title=root.querySelector('.title h1');if(title)title.dataset.inLang='';const subtitle=root.querySelector('.title .sub');if(subtitle)subtitle.dataset.inLang='';
  localizeDiscovery();
  const d=await api('/api/tier-list');const names={S:'S Tier',A:'A Tier',B:'B Tier',C:'C Tier'};const t={...IN_LANG.en,...(IN_LANG[activeLanguage]||{}),...(COMMUNITY_LANG[activeLanguage]||{}),...(RANKING_LANG[activeLanguage]||{})};$('#tiers').innerHTML=Object.entries(d.tiers||{}).map(([k,items])=>`<section class="tierPanel"><h2 data-in-lang>${names[k]||k}</h2><div class="miniGrid">${items.map(n=>`<a class="miniCard" href="/novel/${n.id}"><img src="${img(n.cover_url,n.title)}" alt=""><b>${esc(n.title)}</b><span>${esc(n.author||t.Unknown)} · ★ ${Number(n.rating||0).toFixed(1)}</span></a>`).join('')||'<div class="empty" data-in-lang>No novels here yet.</div>'}</div></section>`).join('');localizeDiscovery();return;
 }
 if(kind==='random'){
  root.innerHTML=pageStart('Random Novel','One button. One story. Zero browsing indecision.')+`<div class="panel randomPanel"><div id="randomResult" class="empty">Ready to discover something unexpected.</div><button id="spinRandom" class="primary">🎲 Discover a Random Novel</button></div></div></div>`;localizeDiscovery();const load=async()=>{const n=await api('/api/random');$('#randomResult').innerHTML=n?`<article class="randomCard"><img src="${img(n.cover_url,n.title)}" alt=""><div><div class="eyebrow">Your random discovery</div><h2>${esc(n.title)}</h2><p class="muted">${esc(n.author||'Unknown author')}</p><p>★ ${Number(n.rating||0).toFixed(1)} · ${Number(n.chapter_count||0)} chapters · ${Number(n.views||0).toLocaleString()} views</p><a class="primary" href="/novel/${n.id}">Open Novel →</a></div></article>`:'<div class="empty">No published novels are available yet.</div>';localizeDiscovery()};$('#spinRandom').onclick=load;return;
 }
 if(kind==='made-for-you'){
  root.innerHTML=pageStart('Made For You','Recommendations based on your library and the public Imperial catalog.')+`<div class="notice" id="recNotice">Loading recommendations...</div><div id="recGrid" class="grid" style="margin-top:18px"></div></div></div>`;localizeDiscovery();const d=await api('/api/made-for-you');$('#recNotice').textContent=d.personalized?'Personalized for your account.':'Showing popular catalog stories. Sign in for a more personalized library experience.';$('#recGrid').innerHTML=(d.results||[]).map(card).join('')||'<div class="empty" style="grid-column:1/-1">No recommendations yet.</div>';localizeDiscovery();return;
 }
 if(kind==='vote'){
  root.innerHTML=pageStart('Vote Novels','Vote on open requests to help the community surface what readers want reviewed.')+`<div class="panel"><div id="voteList" class="chapterList"></div></div></div></div>`;localizeDiscovery();async function load(){const rows=await api('/api/vote-novels');$('#voteList').innerHTML=rows.length?rows.map(r=>`<div class="chapter voteRow"><span class="chapterNo">${Number(r.votes||0)}<small> votes</small></span><span><b>Request #${r.id}</b><br><span class="muted">${esc(r.source_host)} · ${esc(r.url)}</span></span><button class="ghost voteBtn" data-id="${r.id}">Vote</button></div>`).join(''):'<div class="empty">No open novel requests yet. <a href="/requests">Submit a request</a>.</div>';localizeDiscovery();$('.voteBtn').forEach(b=>b.onclick=async()=>{try{const d=await api('/api/vote-novels',{method:'POST',body:JSON.stringify({request_id:Number(b.dataset.id)})});b.textContent=d.voted?'Voted ✓':'Vote';localizeDiscovery();load()}catch(e){alert(e.message)}})}load();return;
 }
 if(kind==='notifications'){
  root.innerHTML=pageStart('Notifications','Updates about chapters, follows, requests and your Imperial account.')+`<div class="panel"><div class="actions"><button id="markRead" class="ghost">Mark all as read</button></div><div id="noticeList" class="chapterList"></div></div></div></div>`;localizeDiscovery();try{const d=await api('/api/notifications');$('#noticeList').innerHTML=d.length?d.map(x=>`<div class="chapter ${x.read_at?'':'unreadNotice'}"><span class="chapterNo">${x.read_at?'✓':'●'}</span><span><b>${esc(x.title)}</b><br><span class="muted">${esc(x.body)} · ${esc(x.created_at)}</span></span></div>`).join(''):'<div class="empty">No notifications yet.</div>'}catch(e){$('#noticeList').innerHTML=`<div class="notice">${esc(e.message)} <a href="/login">Sign in</a></div>`}$('#markRead').onclick=async()=>{try{await api('/api/notifications/read',{method:'POST'});discoveryPage('notifications')}catch(e){alert(e.message)}};return;
 }
}
function simplePage(title='Page not found',sub='The page you requested does not exist.'){const root=$('#app');root.innerHTML=pageStart(title,sub)+`<section class="panel notFoundPanel"><div class="eyebrow">IMPERIAL GATEWAY</div><h2>We could not find that realm.</h2><p>Check the address or return to the Imperial Novel library.</p><div class="actions"><a class="primary" href="/">Return Home</a><a class="secondary" href="/catalog">Explore Catalog</a><a class="ghost" href="/search">Search Stories</a></div></section></div></div>`}
