  $$('.authorChapterEditToggle',manager).forEach(b=>b.onclick=()=>{const f=$('.authorChapterEditForm',b.closest('.authorChapterManageRow'));if(f)f.hidden=!f.hidden});
  $$('.authorChapterEditCancel',manager).forEach(b=>b.onclick=()=>{b.closest('form').hidden=true});
  $$('.authorChapterEditForm',manager).forEach(f=>{const localDraft=attachLocalDraft(f,'chapter-edit:'+Number(f.dataset.id));f.onsubmit=async ev=>{ev.preventDefault();const fd=new FormData(f),payload={chapter_number:Number(fd.get('chapter_number')),title:String(fd.get('title')||'').trim(),content:String(fd.get('content')||''),is_locked:fd.get('is_locked')==='on',ticket_cost:Number(fd.get('ticket_cost')||0)};const save=$('button[type="submit"]',f);save.disabled=true;try{const result=await api('/api/author/chapters/'+Number(f.dataset.id),{method:'PATCH',body:JSON.stringify(payload)});localDraft.clear();setNotice(result.message||'Chapter saved.');manager.hidden=true;await openAuthorChapterManager({dataset:{id:String(novelId),kind:button.dataset.kind}},list,setNotice)}catch(error){setNotice(error.message||'Could not save chapter changes.',true)}finally{save.disabled=false}}});
