 const applyAuthorStudioLanguage=()=>{const lang=document.documentElement.lang||'en';root.querySelectorAll('h1,h2,h3,h4,b,button,a,label,legend,p,span,small,option,div').forEach(el=>{if(el.children.length===0){const key=el.textContent.trim();if(AUTHOR_STUDIO_LANG.en[key])el.dataset.inLang=''}});setINLang(lang)};
